import { useRef } from 'react'
import './CustomInput.css'

const CustomInput = function({ cref,type,label,min,max,step,value,onchange,style,substyle,labelstyle }) {
    const labelRef = useRef(null)

    return (
        <div className='custom-input' style={{...style,minWidth: labelRef.current ? `${Number(labelRef.current.offsetWidth) + 40}px` : ''}}>
            <div className='custom-input__label' ref={labelRef} style={labelstyle}>{label}</div>
            <input ref={cref} type={type} min={min} max={max} step={step} value={value} onChange={onchange} style={substyle}/>
        </div>
    )
}

export default CustomInput