import './cabinets.css'
import icons from '../../icons/icons';
import Cabinet from '../Cabinet/cabinet';
import { useParams, useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import axios from 'axios';
import Modal from '../Modal/Modal';
import Filters from '../filters/Filters'
import { toast } from 'sonner';
import CustomInput from '../../subComponents/CustomInput/CustomInput';
import CustomSelect from '../../subComponents/CustomSelect/CustomSelect';

const Cabinets = function(props) {
    const {id,status} = useParams()
    const [cabinets,setCabinets] = useState(null)
    const [modalActive,setModalActive] = useState(false)
    const [action,setAction] = useState('')
    const [cabinetId,setCabinetId] = useState(null)
    const [filterTitle,setFilterTitle] = useState('')
    const [filterType,setFilterType] = useState('Все')

    const navigate = useNavigate()

    const url = 'http://127.0.0.1:8000/core_api/room/'

    const axiosInstance = axios.create({
        headers: {
          'Content-Type': 'application/json',
          'Authorization':`Token ${localStorage.getItem('authToken')}`
        }
    })

    useEffect(() => {
        axiosInstance.get(url,{params:{filter_building_id:id}})
            .then(data => setCabinets(data.data.results))
            .catch(e => console.log(e))
    }, [])

    const goBack = () => navigate(-1)

    const showModal = function() {
        setModalActive(true)
        setAction('addCabinet')
    }

    const addCabinet = async function(number,type) {
        let data = {
            building_id:Number(id),
            number:number,
            type:type
        }

        let updateCabinets = function(data) {
            setCabinets([...cabinets,{id:data.data.id,number:number,type:type,count_free_socket:0}])
            toast.success(
                <div className='toast-message--success'>{icons.success} Помещение {data.data.number} было успешно создано!</div>,
                {duration:5000,position:'bottom-left'}
            )
        }

        await axiosInstance.post(url,data)
            .then(data => updateCabinets(data))
            .catch(e => console.log(e))

            setAction('')
    }

    const confirmDeletion = function(id) {
        setCabinetId(id)
        setAction('delCabinet')
        setModalActive(true)
    }

    const deleteCabinet = async function(state) {
        if (state === true) {
            let url = `http://127.0.0.1:8000/core_api/room/${cabinetId}/`
            let cabName = cabinets.find(item => item.id === cabinetId).number

            let updateCabinets = function() {
                setCabinets(cabinets => cabinets.filter(item => item.id !== cabinetId))
                setAction('addCabinet')
                setCabinetId(null)
                toast.success(
                    <div className='toast-message--success'>{icons.success} Помещение {cabName} было успешно удалено!</div>,
                    {duration:5000,position:'bottom-left'}
                )
            }

            await axiosInstance.delete(url)
                .then(data => updateCabinets())
                .catch(e => console.log(e))

            setAction('')
        }
        else {
            setAction('')
            setCabinetId(null)
        }
    }

    const applyFilters = function(data) {
        let filteredData = data

        filterTitle === '' ? 
        filteredData = filteredData : 
        filteredData = filteredData.filter(item => item.number.toLowerCase().includes(filterTitle))

        filterType === 'Все' ?
        filteredData = filteredData : 
        filteredData = filteredData.filter(item => item.type === filterType)

        console.log(filteredData)

        return filteredData
    }

    return(
        <div className={!props.navbarHidden ? 'cabinets' : 'cabinets cabinets--blured'}>
            {/* <Filters id={id}/> */}
            <p className='cabinets__title'>{`Помещения:`}</p>
            <div className='cabinets__filter'>
                <div className='cabinets__filter__body'>
                    <CustomInput 
                        type='text' 
                        label='Поиск помещения' 
                        substyle={{fontSize:'1.5rem',padding:'3px'}}
                        labelstyle={{fontSize:'1.2rem',top:'-0.6rem'}}
                        onchange={(e) => setFilterTitle(e.target.value.toLowerCase())}
                    />
                    <CustomSelect
                        placeholder={'<Тип помещения>'} 
                        label={'Тип помещения'}
                        labelstyle={{fontSize:'1.2rem',top:'-0.6rem'}}
                        subStyle={{fontSize:'1.5rem'}}
                        editable={false}
                        options={['Все','Обычная','Серверная']} 
                        value={'Все'}
                        getValue={(value) => setFilterType(value)}
                    />
                </div>
            </div>
            <div className='cabinets__wrapper'>
                <div className='cabinets__wrapper__add-new' onClick={showModal}>
                    {icons.cabinets.plus}
                    <p className='cabinets__wrapper__add-new__title'>Добавить</p>
                </div>
                {!cabinets ? '' : applyFilters(cabinets).map(elem => (
                    <Cabinet 
                        id={elem.id} 
                        name={elem.number} 
                        type={elem.type}
                        delCabinet={confirmDeletion}
                    />
                ))}
            </div>
            <Modal
                active={modalActive}
                setActive={setModalActive}
                action={action}
                getResult={action === 'addCabinet' ? addCabinet : deleteCabinet}
            />
        </div>
    );
}

export default Cabinets;