import './TreeNode.css'
import icons from '../../../icons/icons'
import { useState } from 'react'

const TreeNode = function({id,type,label,children}) {
    const [expanded,setExpanded] = useState(false)

    return (
        <div className='tree__node'>
            <div className='tree__node__body' onClick={() => setExpanded(prevValue => !prevValue)}>
                <div className='tree__node__body__icon'>{type === 'folder' ? expanded ? icons.folder_opened : icons.folder : icons.file}</div>
                <div className='tree__node__body__title'>{label}</div>
            </div>
            <div className='tree__node__content'>
                {expanded ? children.map(item => 
                    <TreeNode
                        id={item.id}
                        type={item.type}
                        label={item.label}
                        children={item.children}
                    />
                ) : ''}
            </div>
        </div>
    )
}

export default TreeNode