import './SchemeNote.css'
import icons from '../../../icons/icons'
import { useState, useEffect } from 'react'
import axios from 'axios'
import { Tooltip } from 'react-tooltip'
import { useNavigate } from 'react-router-dom'

const SchemeNote = function({id,title,isCurrent,setCurrent,onDelete}) {
    const [buildingCount,setBuildingCount] = useState(null)
    const [users,setUsers] = useState(null)
    const [showTools,setShowTools] = useState(false)

    const navigate = useNavigate(null)

    const axiosInstance = axios.create({
        headers: {
          'Content-Type': 'application/json',
          'Authorization':`Token ${localStorage.getItem('authToken')}`
        }
    })

    useEffect(() => {
        let url = `http://127.0.0.1:8000/core_api/building/`
        let url1 = 'http://127.0.0.1:8000/core_api/access/'

        let fetchData = async function() {
            await axiosInstance.get(url,{params:{filter_scheme_id:Number(id)}})
                .then(data => setBuildingCount(data.data.length))
                .catch(e => console.log(e))

            await axiosInstance.get(url1,{params:{filter_scheme_id:Number(id)}})
                .then(data => setUsers(data.data.results))
                .catch(e => console.log(e))
        }

        fetchData()
    }, [id])

    const deleteScheme = function() {
        onDelete(id)
    }

    return (
        <>
            <Tooltip 
                style={{backgroundColor:'rgb(0,48,143)',color:'white',fontSize:'1.75rem',zIndex:1000}} 
                anchorSelect='.schemes__list__body__item__count__element--users' 
                place='right' 
                content='Управление доступом' 
            />
            <div 
                className={isCurrent ? 'schemes__list__body__item schemes__list__body__item--current' : 'schemes__list__body__item'} 
                onClick={(e) => {
                    if (e.target.classList.contains('schemes__list__body__item')) {
                        setCurrent(id)
                    }
                }} 
                onMouseEnter={() => setShowTools(true)} 
                onMouseLeave={() => setShowTools(false)}
            >
                { showTools ? <div className='schemes__list__body__item__delete' onClick={deleteScheme}>{icons.circleDelete}</div> : ''}
                <div className='schemes__list__body__item__count__element'>{icons.building} {buildingCount}</div>
                <div className='schemes__list__body__item__title'>{title}</div>
                <div 
                    className='schemes__list__body__item__count__element schemes__list__body__item__count__element--users' 
                    onClick={() => {navigate(`/userList/${id}/`,{state:{description:`Пользователи ${title}`}})}}
                >
                    {icons.user} {users ? users.length : '?'}
                </div>
            </div>
        </>
    )
}

export default SchemeNote