import './Info.css'
import { Tooltip } from 'react-tooltip'
import icons from '../../../icons/icons'
import { useNavigate } from 'react-router-dom'
import axios from 'axios'

const Info = function({data}) {
    const navigate = useNavigate(null)

    const liStyle = {
        color:'white',
        textAlign:'left',
        fontSize:'1.2rem',
        textWrap:'nowrap',
        padding:'0',
        listStyle:'none'
    }

    const axiosInstance = axios.create({
        headers: {
          'Content-Type': 'application/json',
          'Authorization':`Token ${localStorage.getItem('authToken')}`
        }
    })

    const toEndpoint = function() {
        let url = 'http://127.0.0.1:8000/core_api/equipment/'
        let rackId = Number(data.server_rack.id)

        let translate = function(eq) {
            let deviceId = eq.id
            let title = `${eq.template.manufacturer} ${eq.template.model}`

            if (eq.template.type === 'Коммутатор') {
                navigate(`/device/${deviceId}`,{state:{description:`${title}`}})
            }
            else if (eq.template.type === 'Пассивное оборудование') {
                navigate(`/patch-panel/${deviceId}`,{state:{description:`${title}`}})
            }
        }

        axiosInstance.get(url,{params:{filter_server_rack_id:rackId}})
            .then(d => {
                translate(d.data.results.find(item => item.template.model === data.equipment.model))
            })
            .catch(e => console.log(e))
    }

    return (
        <div className='info' data-tooltip-id={`conInfo${data.port.id}`} data-tooltip-place='top'>
            {icons.info}
            <div className='info__link' onClick={toEndpoint}>{icons.link}</div>
            <Tooltip id={`conInfo${data.port.id}`} style={{backgroundColor:'rgb(0,48,143)'}}>
                <ul>
                    <li style={liStyle}>{`Здание: ${data.building.number}`}</li>
                    <li style={liStyle}>{`Помещение: ${data.room.number}`}</li>
                    <li style={liStyle}>{`Серверная стойка: ${data.server_rack.title}`}</li>
                    <li style={liStyle}>{`Юнит: ${data.unit.uid} (${data.unit.side})`}</li>
                    <li style={liStyle}>{`Оборудование: ${data.equipment.manufacturer} ${data.equipment.model}`}</li>
                    <li style={liStyle}>{`Порт: ${data.port.uid} (${data.port.ip ? data.port.ip : 'null'})`}</li>
                </ul>
            </Tooltip>
        </div>
    )
}

export default Info